<script setup lang="ts">
const db=useDb(),w=useWorkspace(),search=ref('')
const {data,error}=await useAsyncData('enquiries',async()=>check(await db.from('quolyn_enquiries').select('*,quolyn_customers(name),quolyn_enquiry_lines(state)').eq('workspace_id',w.value!.id).order('created_at',{ascending:false})))
const rows=computed(()=>data.value?.filter(e=>e.title.toLowerCase().includes(search.value.toLowerCase())))
</script>
<template><div><div class="page-title"><div><div class="eyebrow">REQUESTS INTO REQUIREMENTS</div><h1>Enquiries</h1><p>The original request, your interpretation, and every decision in between.</p></div><NuxtLink to="/enquiries/new" class="primary">＋ New enquiry</NuxtLink></div><p v-if="error" class="alert error">{{error.message}}</p><div class="toolbar"><input v-model="search" aria-label="Search enquiries" placeholder="Search enquiries…"></div><div class="table-wrap"><table v-if="rows?.length"><thead><tr><th>ENQUIRY</th><th>CUSTOMER</th><th>SOURCE</th><th>RECEIVED</th><th>REVIEW PROGRESS</th></tr></thead><tbody><tr v-for="e in rows" :key="e.id"><td><NuxtLink :to="'/enquiries/'+e.id" class="table-link">{{e.title}}</NuxtLink></td><td>{{e.quolyn_customers?.name||'Not assigned'}}</td><td>{{e.source}}</td><td>{{e.received_date}}</td><td><span class="pill">{{e.quolyn_enquiry_lines.filter((l:any)=>['confirmed','excluded'].includes(l.state)).length}} / {{e.quolyn_enquiry_lines.length}} reviewed</span></td></tr></tbody></table><div v-else class="empty"><div class="empty-icon">↙</div><h3>No enquiries yet</h3><p>Start with a real customer request, pasted exactly as received.</p><NuxtLink to="/enquiries/new" class="secondary">Create enquiry →</NuxtLink></div></div></div></template>
